String dciRef = tools.getParameterPage().getString("thumbnailRef");

try {    
    String[] dciRefTokens = dciRef.split("/");

    if(dciRefTokens.length == 5) {      	
      	String nameAndType = dciRefTokens[4];
      	int index = nameAndType.lastIndexOf(".");
        dciName = nameAndType.substring(0, index);
        dciType = nameAndType.substring(index + 1, nameAndType.length());
        dciPath = "/" + dciRefTokens[3] + "/";		
    }
} catch(Exception e) {
  	oLog.error("Failed to remove thumbnail " + dciRef);
}
